#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a raw UObject pointer (UArenaScoreTracker*) missing the UPROPERTY() macro in ArenaGameMode.h, so Unreal's garbage collector does not see the reference and purges the NewObject<UArenaScoreTracker>(this) instance after ~60 seconds (at [2026.10.28-21.05.13:071] LogGarbage), leaving a dangling pointer that causes an EXCEPTION_ACCESS_VIOLATION when AArenaGameMode::OnGoalScored calls ScoreTracker->AddPoints.",
  "no_colors_cause": "AArenaGameMode::BeginPlay dynamically loads '/Game/Data/Palettes/DA_Primary.DA_Primary' via LoadObject<UArenaPalette> with a string literal rather than a hard asset reference, and Config/DefaultGame.ini sets bCookAll=False while only cooking /Game/Maps/Arena and /Game/Data/Effects (omitting /Game/Data/Palettes from +DirectoriesToAlwaysCook). Because the cooker does not discover string-path dynamic loads, DA_Primary is excluded from the packaged pak file, causing LoadObject to return nullptr and the HUD to fall back to gray."
}
